import sys


def read_lines(path):
    with open(path) as f:
        return f.readlines()


def count_words(lines):
    total = 0
    for line in lines:
        total += len(line.split())
    return total


def main():
    lines = read_lines(sys.argv[1])
    print(count_words(lines))
import json


def encode(obj):
    return json.dumps(obj, sort_keys=True)


def decode(text):
    return json.loads(text)


def roundtrip(obj):
    return decode(encode(obj))
import time


def now():
