import random


def roll():
    return random.randint(1, 6)


def roll_many(n):
    return [roll() for _ in range(n)]


def best_of(n):
    return max(roll_many(n))
import re


def strip_tags(html):
    return re.sub(r'<[^>]+>', '', html)


def squeeze(text):
    return re.sub(r'\s+', ' ', text).strip()


def clean(html):
    return squeeze(strip_tags(html))
